CREATE TABLE employees (
  id INT PRIMARY KEY,
  name VARCHAR(255),
  manager_id INT
);

SELECT e1.name AS employee, e2.name AS manager
FROM employees e1
JOIN employees e2 ON e1.manager_id = e2.id;

